pub type TrafficLight = enum {
  Red,
  Yellow,
  Green,
}

fn action(light: &TrafficLight) -> Str {
  match light {
    Red => { return "Stop"; }
    Yellow => { return "Slow Down"; }
    Green => { return "Go"; }
  }
}

fn main() -> Int {
  let result = action(&TrafficLight.Red);
  return 0;
}
